    private void ShowCreateForm()
    {
        showCreateForm = true;
        newShipment = new();
        estimatedDeliveryDate = DateTime.Today.AddDays(7);
    }

    private void CancelCreate() => showCreateForm = false;

    private async Task CreateShipment()
    {
        isSaving = true;
        newShipment.EstimatedDelivery = estimatedDeliveryDate;
        try
        {
            var created = await ShipmentService.CreateShipmentAsync(newShipment);
            shipments.Insert(0, created);
            showCreateForm = false;
        }
        finally
        {
            isSaving = false;
        }
    }

    private void StartEdit(Shipment s)
    {
        editingShipmentId = s.Id;
        editStatus = s.Status;
    }

    private void CancelEdit() => editingShipmentId = null;

    private async Task SaveStatus(Shipment s)
    {
        s.Status = editStatus;
        await ShipmentService.UpdateShipmentAsync(s);
        editingShipmentId = null;
    }

